mapper.sql:
FROM saving_group sg JOIN `groups` g ON g.group_id = sg.group_id JOIN region r ON r.region_id = g.region_id
g.deleted_at IS NULL
AND (g.group_name LIKE CONCAT('%', #{keyword}, '%') OR g.description LIKE CONCAT('%', #{keyword}, '%'))
AND r.region_name = #{regionName}
AND sg.status = #{status}
